import {demoRows,trainDemo} from './xgboost-model.js';
const $=s=>document.querySelector(s);
function styles(){if(document.querySelector('[data-xgb-style]'))return;const link=document.createElement('link');link.rel='stylesheet';link.href='/xgboost.css';link.dataset.xgbStyle='';document.head.append(link)}

export function addXGBoostLink(){
 styles();const link=document.createElement('a');link.className='xgb-door';link.id='xgboost-link';link.href='/xgboost/';
 link.innerHTML='<div><span class="eyebrow">ИДЕЯДАН — ҚҰРАЛҒА</span><h3>XGBoost</h3><p>Gradient Boosting негізін түсіндің. Енді осы идеяның қуатты іске асырылымын зертте.</p><div class="xgb-door-tags"><span>Регуляризация</span><span>Градиент + Гессиан</span><span>Жаңа сабақ</span></div></div><span class="xgb-door-arrow" aria-hidden="true">↗</span>';
 $('#step-4').append(link);
 const next=$('.next-chapter');next.querySelector('h2').textContent='Келесі қадам — XGBoost.';next.querySelector('p').textContent='Қатені түзетуге модельдің күрделілігін бақылауды қос. Жаңа сабақта λ мен γ әсерін тексер.';
 const button=next.querySelector('a');button.href='/xgboost/';button.innerHTML='XGBoost-ты зерттеу <span>↗</span>';
}

export function renderXGBoost(){
 styles();document.body.className='xgboost';document.title='XGBoost — OYLAB';
 const footerSource=document.querySelector('footer>a:not(.logo)');if(footerSource){footerSource.href='https://xgboost.readthedocs.io/en/stable/tutorials/model.html';footerSource.textContent='Дереккөз: XGBoost ↗'}
 const desc=document.querySelector('meta[name="description"]');if(desc)desc.content='XGBoost: градиенттік бустинг, регуляризация және ағаштың бөліну пайдасын интерактивті мысалмен түсін.';
 $('#main').innerHTML=`<div class="wrap xgb-page"><section class="xgb-hero"><a class="xgb-back" href="/gradient-boosting/">← Gradient Boosting сабағына</a><div class="eyebrow">ҚОСЫМША ТАРАУ / 04</div><h1>Сол бустинг.<br><em>Көбірек бақылау.</em></h1><div class="xgb-hero-bottom"><p><b>XGBoost</b> — Extreme Gradient Boosting. Алдыңғы сабақтағы идея сақталады: жаңа ағаштар ортақ болжамды кезекпен жақсартады. Енді әр түзетудің пайдасы мен күрделілігін бірге бағалаймыз.</p><span class="xgb-stamp">XG<br><small>BOOST</small></span></div></section><nav class="xgb-nav" aria-label="XGBoost сабағының бөлімдері"><a href="#xgb-idea">01 Идея</a><a href="#xgb-compare">02 Айырмашылық</a><a href="#xgb-math">03 Математика</a><a href="#xgb-lab">04 Тәжірибе</a><a href="#xgb-quiz">05 Тексеру</a></nav>
 <section class="xgb-section" id="xgb-idea"><span class="eyebrow">01 / ЖАҚСЫ ТҮЗЕТУ ҚАНДАЙ БОЛАДЫ?</span><h2>Қатені азайт.<br>Артық күрделілікті қоспа.</h2><div class="xgb-prose"><p>Мәтінді түзетіп жатырсың деп елестет. Бір сөйлемді жақсарту үшін он жаңа абзац қосудың қажеті бар ма? Модельде де өзгерістің пайдасын оның күрделілігімен салыстырған дұрыс.</p><p><b>Gradient Boosting — жалпы тәсіл.</b> XGBoost — сол тәсілді жүзеге асыратын оңтайландырылған кітапхана. Оның ағаштық бустингінде болжам қатесімен қатар ағаштың күрделілігі де мақсатты функцияға кіреді.</p></div><div class="xgb-objective"><span>БОЛЖАМ ҚАТЕСІ</span><b>+</b><span>КҮРДЕЛІЛІК ШТРАФЫ</span><b>→</b><span>ТЕҢГЕРІМДІ МОДЕЛЬ</span></div></section>
 <section class="xgb-section" id="xgb-compare"><span class="eyebrow">02 / НЕ ӨЗГЕРДІ?</span><h2>Негіз бір. Іске асыруы бай.</h2><div class="xgb-table-wrap"><table><thead><tr><th>Қыры</th><th>Алдыңғы оқу зертханасы</th><th>XGBoost кітапханасы</th></tr></thead><tbody><tr><td>Негізгі идея</td><td>Ағаштарды кезекпен қосу</td><td>Ағаштық бустингте сол идея</td></tr><tr><td>Біздің MSE мысалы</td><td>Қалдықтарды үйрену</td><td>Бірінші және екінші туындыны пайдалану</td></tr><tr><td>Күрделілікті бақылау</td><td>Тереңдік, η, ағаш саны</td><td>Бұларға қосымша λ, α, γ секілді параметрлер</td></tr><tr><td>Бос мәндер</td><td>Біздің мысалда жоқ</td><td>Ағаштар бос мәнге бағытты үйрене алады</td></tr><tr><td>Есептеу</td><td>Браузердегі шағын есеп</td><td>Оңтайландырылған CPU және GPU тәсілдері</td></tr></tbody></table></div><p class="xgb-note">Басқа Gradient Boosting кітапханалары да регуляризация мен жылдам оқыту тәсілдерін қолдана алады. XGBoost кез келген деректе міндетті түрде дәлірек болады деген кепілдік жоқ.</p></section>
 <section class="xgb-section" id="xgb-math"><span class="eyebrow">03 / ТҮЗЕТУДІ ҚАЛАЙ БАҒАЛАЙМЫЗ?</span><h2>Бағыт. Қисықтық. Шектеу.</h2><div class="xgb-concepts"><article><span>g</span><h3>Градиент</h3><p>Болжамды өзгерткенде қате қай бағытта өзгеретінін сипаттайды.</p></article><article><span>h</span><h3>Гессиан</h3><p>Қатенің қисықтығын сипаттайтын екінші туынды. Мұнда әр нүктеде h = 1.</p></article><article><span>λ / γ</span><h3>Регуляризация</h3><p>λ жапырақтағы түзетуді тежейді. γ пайдасы жеткіліксіз бөлуді тоқтата алады.</p></article></div><p>Төмендегі мысалда бір нүктенің шығыны ℓ = ½(ŷ − y)². Сондықтан g = ŷ − y, h = 1. Бір жапырақ үшін G — градиенттер қосындысы, H — екінші туындылар қосындысы.</p><div class="formula">w* = −G / (H + λ)</div><p>Бұл — жапырақ ұсынатын түзету. Ортақ болжамға оның η бөлігі қосылады. Ал түйінді екіге бөлу пайдасы:</p><div class="formula xgb-gain-formula">Gain = ½[Gᴸ²/(Hᴸ+λ) + Gᴿ²/(Hᴿ+λ) − G²/(H+λ)] − γ</div><p>Gain &gt; 0 болса, осы жеңілдетілген мысалда бөлу қабылданады. Мұндағы γ — қосымша бір жапыраққа кететін күрделілік құны. Кітапханада бұдан басқа шектеулер де болуы мүмкін.</p><p class="xgb-note">MSE үшін қалдықтар — теріс градиент. Бұл басқа шығын функцияларының бәрінде дәл осылай болмайды.</p></section>
 <section class="xgb-section" id="xgb-lab"><span class="eyebrow">04 / ӨЗІҢ ТЕКСЕР</span><h2>Жаңа тармақ өз құнын ақтай ма?</h2><p>λ мәнін арттыр: жапырақ салмақтары өзгереді. γ мәнін арттыр: бөлудің таза пайдасы азаяды. Параметр өзгерсе, сол қадам саны жаңа мәндермен қайта есептеледі.</p><div class="xgb-lab"><div class="xgb-lab-title"><strong>REGULARIZATION LAB</strong><span>Нақты есеп · 8 нүкте</span></div><div id="xgb-chart"></div><div class="xgb-legend"><span>● Шын мәндер</span><span>━ Болжам</span></div><div class="xgb-sliders">${slider('xgb-lambda','λ · L2 регуляризация',0,10,1,.1)}${slider('xgb-gamma','γ · Бөлу құны',0,10,0,.1)}${slider('xgb-rate','η · Түзету үлесі',.05,1,.3,.05)}</div><div class="xgb-actions"><button id="xgb-add" class="btn small">Келесі ағаш +</button><button id="xgb-reset" class="btn secondary small">Басынан ↻</button><span>Итерация: <b id="xgb-step">1</b> / 20</span><span>Train MSE: <b id="xgb-mse"></b></span></div><div id="xgb-calculation" aria-live="polite"></div></div><p class="xgb-note">Бұл XGBoost кітапханасын іске қоспайды. Оның негізгі формулаларын түсіндіретін шағын оқу моделі: бір белгі, тереңдігі 1 ағаштар, ½ квадраттық шығын, λ және γ. Бұл жердегі MSE — тек осы сегіз оқыту нүктесінің қатесі.</p></section>
 <section class="xgb-section" id="xgb-quiz"><span class="eyebrow">05 / ӨЗІҢДІ ТЕКСЕР</span><h2>Негізгі ой есіңде ме?</h2><div class="quiz-item"><p>Осы мысалда γ артса, не болуы мүмкін?</p><div class="quiz-options"><button data-xgb-answer="wrong">Барлық бөлу міндетті түрде қабылданады</button><button data-xgb-answer="correct">Пайдасы аз бөлу қабылданбайды</button><button data-xgb-answer="wrong">Ағаштар тәуелсіз оқытылады</button></div><p id="xgb-feedback" aria-live="polite"></p></div></section>
 <section class="xgb-section xgb-sources"><span class="eyebrow">РЕСМИ ДЕРЕККӨЗДЕР</span><a href="https://xgboost.readthedocs.io/en/stable/tutorials/model.html" target="_blank" rel="noopener">Ағаштық бустинг және регуляризация ↗</a><a href="https://xgboost.readthedocs.io/en/stable/faq.html" target="_blank" rel="noopener">Бос мәндер туралы FAQ ↗</a><a href="https://xgboost.readthedocs.io/en/stable/gpu/" target="_blank" rel="noopener">GPU мүмкіндіктері ↗</a></section><div class="xgb-end"><a class="btn secondary" href="/gradient-boosting/">← Gradient Boosting-ке қайту</a><a href="/">Оқу бағытына оралу ↗</a></div></div>`;
 let params={lambda:1,gamma:0,rate:.3,steps:1};
 function update(){
  const result=trainDemo(params),last=result.trees.at(-1);
  $('#xgb-step').textContent=params.steps;$('#xgb-mse').textContent=result.mse.toFixed(4);$('#xgb-add').disabled=params.steps>=20;
  for(const [id,key]of[['xgb-lambda','lambda'],['xgb-gamma','gamma'],['xgb-rate','rate']])$('#'+id+'-out').textContent=params[key].toFixed(2);
  $('#xgb-chart').innerHTML=chart(result);
  if(!last){$('#xgb-calculation').innerHTML=`<p>Алғашқы болжам — нысаналы мәндердің орташа саны: <b>${result.base.toFixed(3)}</b>. Жаңа ағаш қос.</p>`;return}
  $('#xgb-calculation').innerHTML=`<div class="xgb-decision ${last.split?'accepted':'rejected'}"><strong>${last.split?'БӨЛУ ҚАБЫЛДАНДЫ':'БӨЛУ ҚАБЫЛДАНБАДЫ'}</strong><span>Соңғы қадамдағы ең жақсы Gain: <b>${last.gain.toFixed(4)}</b></span></div><div class="xgb-leaves"><div><span>Сол жақ · ${last.leftCount} нүкте</span><p>Gᴸ = ${last.GL.toFixed(3)} · Hᴸ = ${last.HL}</p><b>wᴸ = ${last.leftWeight.toFixed(4)}</b></div><div><span>Оң жақ · ${last.rightCount} нүкте</span><p>Gᴿ = ${last.GR.toFixed(3)} · Hᴿ = ${last.HR}</p><b>wᴿ = ${last.rightWeight.toFixed(4)}</b></div></div><p class="xgb-calculation-note">${last.split?`Шек: x ≤ ${last.threshold.toFixed(2)}. Болжамға η × w қосылады.`:'Екі жапырақты бөлу орнына бір түйіннің түзетуі қолданылады.'}</p>`;
  if(!last.split)document.querySelector('.xgb-leaves').outerHTML=`<div class="xgb-root-leaf">Бір түйін · ${last.H} нүкте<br>G = ${last.G.toFixed(3)} · H = ${last.H}<br><b>w = ${last.leftWeight.toFixed(4)}</b><p>Қабылданбаған бөлу кандидатының шегі: ${last.candidateThreshold.toFixed(2)}.</p></div>`;
 }
 for(const [id,key]of[['xgb-lambda','lambda'],['xgb-gamma','gamma'],['xgb-rate','rate']])$('#'+id).oninput=e=>{params[key]=+e.target.value;update()};
 $('#xgb-add').onclick=()=>{params.steps=Math.min(20,params.steps+1);update()};$('#xgb-reset').onclick=()=>{params.steps=0;update()};
 document.querySelectorAll('[data-xgb-answer]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-xgb-answer]').forEach(x=>{x.className='';x.setAttribute('aria-pressed','false')});const good=b.dataset.xgbAnswer==='correct';b.className=good?'correct':'wrong';b.setAttribute('aria-pressed','true');$('#xgb-feedback').textContent=good?'Дұрыс! γ бөлудің таза пайдасын азайтады. Gain оң болмаса, жаңа бөлу қабылданбайды.':'Тағы ойланып көр: γ — қосымша бөлудің құны.'});update();
}
function slider(id,label,min,max,value,step){return `<div class="control"><label for="${id}">${label}<output id="${id}-out">${value}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`}
function chart(model){
 const x=v=>60+(v-demoRows[0].x)/(demoRows.at(-1).x-demoRows[0].x)*780,y=v=>260-v*48;
 let svg='<svg viewBox="0 0 900 300" role="img" aria-label="Шын мәндер мен реттелген бустинг болжамдары">';
 for(let i=0;i<=5;i++)svg+=`<path d="M60 ${y(i)}H840" stroke="var(--line)"/><text x="40" y="${y(i)+4}" fill="var(--muted)" font-size="10">${i}</text>`;
 demoRows.forEach((r,i)=>{svg+=`<path d="M${x(r.x)} ${y(r.y)}V${y(model.predictions[i])}" stroke="var(--accent)" opacity=".3"/><circle cx="${x(r.x)}" cy="${y(r.y)}" r="5" fill="var(--ink)"/><text x="${x(r.x)}" y="282" text-anchor="middle" fill="var(--muted)" font-size="10">${r.x.toFixed(1)}</text>`});
 const points=[];demoRows.forEach((r,i)=>{if(i)points.push(`${(x(r.x)+x(demoRows[i-1].x))/2},${y(model.predictions[i-1])}`,`${(x(r.x)+x(demoRows[i-1].x))/2},${y(model.predictions[i])}`);points.push(`${x(r.x)},${y(model.predictions[i])}`)});
 return svg+`<polyline points="${points.join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/></svg>`;
}
